import {createGame} from './engine.js';
const $=id=>document.getElementById(id);
const portrait=window.matchMedia('(orientation: portrait)'),motion=window.matchMedia('(prefers-reduced-motion: reduce)');
let game,snapshot={phase:'loading',dialogue:[],actions:[]},userPaused=false,lastFocus=null,messageSignature='',actionSignature='',motionOverride=false;
let preferences={muted:false,speed:1,reducedMotion:motion.matches};
try{const p=JSON.parse(localStorage.getItem('obychnyy-den-ui-v2')||'{}');if(typeof p.muted==='boolean')preferences.muted=p.muted;if([1,2].includes(p.speed))preferences.speed=p.speed;if(typeof p.reducedMotion==='boolean'){preferences.reducedMotion=p.reducedMotion;motionOverride=true;}}catch{}
function savePreferences(){try{localStorage.setItem('obychnyy-den-ui-v2',JSON.stringify(preferences));}catch{}}
function syncPause(){if(!game||!['playing','paused'].includes(snapshot.phase))return;const blocked=userPaused||$('settings').open||portrait.matches||document.hidden;if(blocked&&snapshot.phase==='playing')game.pause();else if(!blocked&&snapshot.phase==='paused')game.resume();}
function fullscreen(){try{const request=document.fullscreenElement?Promise.resolve():$('game').requestFullscreen?.({navigationUI:'hide'});Promise.resolve(request).then(()=>screen.orientation?.lock?.('landscape')).catch(()=>{});}catch{}}
function messages(items){const signature=JSON.stringify(items.map(m=>[m.id,m.text]));if(signature===messageSignature)return;messageSignature=signature;const list=$('messages'),follow=list.scrollHeight-list.scrollTop-list.clientHeight<35;list.replaceChildren();for(const m of items){const li=document.createElement('li');li.className=m.speaker==='Вова'?'sent':'';const name=document.createElement('small');name.textContent=m.speaker;const text=document.createElement('span');text.textContent=m.text;li.append(name,text);list.append(li);}if(follow)list.scrollTop=list.scrollHeight;}
function actions(next){const visible=(next.actions||[]).filter(a=>a.status==='available'||a.status==='running'),signature=JSON.stringify([visible,next.phase]);if(signature===actionSignature)return;actionSignature=signature;for(const side of ['store','school']){const container=$(side+'-actions');container.replaceChildren();for(const a of visible.filter(a=>a.side===side)){const button=document.createElement('button');button.type='button';button.textContent=a.label;button.disabled=a.status!=='available'||next.phase!=='playing';if(a.status==='running'){const note=document.createElement('small');note.textContent='Выполняется…';button.append(note);}button.addEventListener('click',()=>{const result=game.performAction(a.id,a.side);if(!result.accepted)$('announcements').textContent='Это действие сейчас недоступно.';});container.append(button);}}}
function update(next){snapshot=next;const started=['playing','paused','complete'].includes(next.phase);$('start-screen').hidden=started;$('completion').hidden=next.phase!=='complete';$('start').disabled=!game;$('start').textContent='Играть';$('continue').hidden=!next.hasSave;$('continue').disabled=!game;$('hud').hidden=!started||next.phase==='complete';$('pause').textContent=userPaused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',userPaused?'Продолжить':'Пауза');$('sound').setAttribute('aria-pressed',String(next.muted));$('sound').setAttribute('aria-label',next.muted?'Включить звук':'Выключить звук');$('sound').textContent=next.muted?'♫̸':'♪';$('tempo').value=String(next.speed||preferences.speed);$('reduced-motion').checked=Boolean(next.reducedMotion);$('phone').hidden=!started||next.phase==='complete'||!(next.store?.phone.visible||next.school?.phone.visible);messages(next.dialogue||[]);actions(next);}
function start(resume=false){if(!game)return;fullscreen();userPaused=false;game.start({resume});game.setMuted(preferences.muted);game.setSpeed(preferences.speed);game.setReducedMotion(preferences.reducedMotion);syncPause();}
function rotate(){$('rotate').hidden=!portrait.matches;syncPause();}
function openMenu(){if(!game)return;lastFocus=document.activeElement;$('settings').showModal();syncPause();}
function closeMenu(){$('settings').close();syncPause();if(lastFocus?.isConnected&&!lastFocus.disabled)lastFocus.focus();}
$('start').addEventListener('click',()=>start(false));$('continue').addEventListener('click',()=>start(true));$('repeat').addEventListener('click',()=>start(false));$('fullscreen').addEventListener('click',fullscreen);$('rotate-fullscreen').addEventListener('click',fullscreen);
$('pause').addEventListener('click',()=>{userPaused=!userPaused;syncPause();update(snapshot);});$('menu').addEventListener('click',openMenu);$('close-menu').addEventListener('click',closeMenu);$('resume').addEventListener('click',closeMenu);$('settings').addEventListener('cancel',e=>{e.preventDefault();closeMenu();});
$('restart').addEventListener('click',()=>{userPaused=false;$('settings').close();start(false);});$('sound').addEventListener('click',()=>{preferences.muted=!snapshot.muted;game?.setMuted(preferences.muted);savePreferences();});$('tempo').addEventListener('change',()=>{preferences.speed=Number($('tempo').value);game?.setSpeed(preferences.speed);savePreferences();});$('reduced-motion').addEventListener('change',()=>{preferences.reducedMotion=$('reduced-motion').checked;motionOverride=true;game?.setReducedMotion(preferences.reducedMotion);savePreferences();});
portrait.addEventListener('change',rotate);document.addEventListener('visibilitychange',syncPause);motion.addEventListener('change',()=>{if(!motionOverride){preferences.reducedMotion=motion.matches;game?.setReducedMotion(motion.matches);}});document.addEventListener('keydown',e=>{if(e.code==='Space'&&!e.target.closest('button,input,select,textarea,[contenteditable]')&&['playing','paused'].includes(snapshot.phase)){e.preventDefault();userPaused=!userPaused;syncPause();update(snapshot);}});
rotate();
try{game=await createGame({storeCanvas:$('store-canvas'),schoolCanvas:$('school-canvas'),listenVisibility:false,onUpdate:update,onEvent:e=>{if(e.type==='notice'){$('notice').textContent=e.text;$('notice').hidden=false;}if(e.type==='complete')$('announcements').textContent='Первый фрагмент завершён.';}});update(game.getSnapshot());}catch(error){$('start').disabled=true;$('start').textContent='Сцены недоступны';$('load-error').hidden=false;$('load-error').textContent='Не удалось загрузить игру. Обновите страницу.';console.error(error);}
